def codes(fn):
    lines=open(fn,'rb').read().splitlines()
    hdr=lines[0].split(); h=int(hdr[1]); comments=int(hdr[5]); count=int(hdr[8]) if len(hdr)>8 else 0
    idx=1+comments+ (95+7)*h
    res=[]
    for n in range(count):
        if idx>=len(lines): break
        res.append((n,lines[idx], lines[idx+1:idx+1+h])); idx+=1+h
    print(fn, "end idx", idx, len(lines), "count", count)
    for n,c,g in res:
        if n<10 or b'0100' in c or c.startswith(b'-') or b'256' in c:
