import sys, os
def make(path, glyph_map={}, height=1, hardblank=b'$', oldlayout=0, full=None, codes={}):
    # glyph_map char code -> list of bytes rows (without endmark)
    # default glyph: for ascii, row = bytes([code]) if visible else b' '
    lines=[]
    header = b'flf2a'+hardblank+b' %d 1 20 %d 0 0' % (height, oldlayout)
    if full is not None:
        header += b' %d %d' % (full, len(codes))
    lines.append(header)
    def emit(rows):
        # choose endmark @ unless row ends with @? Simple use @ for all except if any row contains ??? We'll use @ and determine
        for i,row in enumerate(rows):
            end=b'@'
            if row.endswith(b'@'):
                end=b'#'
            if i==len(rows)-1:
                lines.append(row+end+end)
            else:
                lines.append(row+end)
    for code in range(32,127):
        if code in glyph_map:
            emit(glyph_map[code])
        else:
            # default: char itself (except space => b' ' )
            emit([bytes([code]) if code!=32 else b' ']*height)
    for code in [196,214,220,228,246,252,223]:
        emit(glyph_map.get(code,[b'D']*height))
    for code,rows in codes.items():
        if isinstance(code, int):
            lines.append(str(code).encode())
        else:
            lines.append(code if isinstance(code,bytes) else code.encode())
        emit(rows)
    data=b'\n'.join(lines)+b'\n'
    open(path,'wb').write(data)
