import glob, zipfile
def lines_of(fn):
 d=open(fn,'rb').read()
 if d.startswith(b'PK'):
  z=zipfile.ZipFile(fn); d=z.read(z.namelist()[0])
 return d.decode('utf-8',errors='surrogateescape').splitlines()
def strip_row(s):
 s=s.rstrip(' \t\r\n\x0b\x0c')
 if not s: return s
 e=s[-1]
 while s and s[-1]==e: s=s[:-1]
 return s
for fn in sorted(glob.glob('fonts/*.flf')+glob.glob('assets/*.flf')+glob.glob('assets/*.tlf')):
 lines=lines_of(fn); hdr=lines[0].split(); h=int(hdr[1]); comm=int(hdr[5]); idx=1+comm; count=0; diffs=[]
 # parse mandatory+german+codetags rough
 glyphs=[]
 for i in range(102):
  glyphs.append(lines[idx:idx+h]); idx+=h
 while idx < len(lines):
  idx+=1; glyphs.append(lines[idx:idx+h]); idx+=h
 for gi,g in enumerate(glyphs):
  lens=[len(strip_row(r)) for r in g]
  if len(set(lens))>1: diffs.append((gi,lens,g))
 print(fn, 'glyphs',len(glyphs),'diff row lens',len(diffs), diffs[:2])
