import subprocess
# build reverse map of mnemonic font codetags
lines=open('fonts/mnemonic.flf').read().splitlines()
# glyphs height1 etc map output string to code using font parse roughly
hdr=lines[0].split(); h=int(hdr[1]); comm=int(hdr[5]); idx=1+comm; mp={}
def strip(s):
 if not s:return s
 e=s[-1]
 while s and s[-1]==e:s=s[:-1]
 return s
for code in range(32,127):
 mp[strip(lines[idx])]=code; idx+=1
for code in [196,214,220,228,246,252,223]:
 mp[strip(lines[idx])]=code; idx+=1
while idx < len(lines):
 c=int(lines[idx].split()[0],0); idx+=1; mp[strip(lines[idx])]=c; idx+=1
def run(inp):
 p=subprocess.run(['./executable','-d','fonts','-f','mnemonic'],input=inp,capture_output=True); return p.stdout.strip().decode()
for b in range(32,128):
 out=run(bytes([27,b,10]))
 print(b,chr(b),out,mp.get(out))
PY
"}

