    memset(&z, 0, sizeof(z));
    z.src = src; z.srclen = srclen; z.dst = dst; z.dstlen = dstlen;
    for (;;) {
        int bfinal = infl_bits(&z, 1);
        int btype = infl_bits(&z, 2);
        if (bfinal < 0 || btype < 0) return -1;
        if (btype == 0) {
            z.bitcnt = 0; z.bitbuf = 0;
            if (z.srcpos + 4 > z.srclen) return -1;
            int len = z.src[z.srcpos] | (z.src[z.srcpos + 1] << 8);
            z.srcpos += 4;
            if (z.srcpos + (size_t)len > z.srclen) return -1;
            if (z.outpos + (size_t)len > z.dstlen) return -1;
            memcpy(z.dst + z.outpos, z.src + z.srcpos, (size_t)len);
            z.outpos += (size_t)len;
            z.srcpos += (size_t)len;
        } else if (btype == 1 || btype == 2) {
            Huff lit, dist;
            unsigned char lengths[288 + 32];
            int nlit, ndist;
            if (btype == 1) {
                nlit = 288; ndist = 32;
                for (int i = 0; i < 288; i++)
                    lengths[i] = (i < 144) ? 8 : (i < 256) ? 9 : (i < 280) ? 7 : 8;
