            } else {
                int hlit = infl_bits(&z, 5);
                int hdist = infl_bits(&z, 5);
                int hclen = infl_bits(&z, 4);
                if (hlit < 0 || hdist < 0 || hclen < 0) return -1;
                nlit = hlit + 257; ndist = hdist + 1;
                if (nlit > 288 || ndist > 32) return -1;
                static const int order[] = {16,17,18,0,8,7,9,6,10,5,11,4,12,3,13,2,14,1,15};
                unsigned char clen[19];
                memset(clen, 0, sizeof(clen));
