                    } else if (sym == 16) {
                        if (idx == 0) return -1;
                        int rep = infl_bits(&z, 2);
                        if (rep < 0) return -1;
                        rep += 3;
                        if (idx + rep > total) return -1;
                        unsigned char prev = lengths[idx - 1];
