                    } else if (sym == 17) {
                        int rep = infl_bits(&z, 3);
                        if (rep < 0) return -1;
                        rep += 3;
                        if (idx + rep > total) return -1;
                        while (rep-- > 0) lengths[idx++] = 0;
                    } else if (sym == 18) {
                        int rep = infl_bits(&z, 7);
                        if (rep < 0) return -1;
