            if (huff_build(&lit, lengths, nlit) < 0) return -1;
            if (huff_build(&dist, lengths + nlit, ndist) < 0) return -1;
            for (;;) {
                int sym = huff_decode(&z, &lit);
                if (sym < 0) return -1;
                if (sym == 256) break;
                if (sym < 256) {
                    if (z.outpos >= z.dstlen) return -1;
                    z.dst[z.outpos++] = (unsigned char)sym;
                } else {
                    int li = sym - 257;
                    if (li < 0 || li >= 29) return -1;
                    int len = len_base[li];
                    int ext = infl_bits(&z, len_ext[li]);
                    if (ext < 0) return -1;
                    len += ext;
                    int dsym = huff_decode(&z, &dist);
                    if (dsym < 0 || dsym >= 30) return -1;
                    int d = dist_base[dsym];
                    int dext = infl_bits(&z, dist_ext[dsym]);
                    if (dext < 0) return -1;
                    d += dext;
                    if ((size_t)d > z.outpos) return -1;
                    if (z.outpos + (size_t)len > z.dstlen) return -1;
                    for (int i = 0; i < len; i++) {
                        z.dst[z.outpos] = z.dst[z.outpos - (size_t)d];
                        z.outpos++;
                    }
                }
            }
        } else {
            return -1;
        }
        if (bfinal) break;
    }
    return (z.outpos == z.dstlen) ? 0 : -1;
}

