static unsigned char **zip_buffers = NULL;
static size_t zip_buffers_n = 0, zip_buffers_cap = 0;
static void keep_zip_buffer(unsigned char *p) {
    if (zip_buffers_n == zip_buffers_cap) {
        zip_buffers_cap = zip_buffers_cap ? zip_buffers_cap * 2 : 8;
        zip_buffers = xrealloc(zip_buffers, zip_buffers_cap * sizeof(*zip_buffers));
    }
    zip_buffers[zip_buffers_n++] = p;
}
typedef struct { FILE *fp; int was_deflated_zip; } ZOpen;
static ZOpen zopen_path(const char *path) {
    ZOpen zo;
    zo.fp = NULL; zo.was_deflated_zip = 0;
    FILE *raw = fopen(path, "rb");
    if (!raw) return zo;
    unsigned char hdr[30];
    size_t n = fread(hdr, 1, 30, raw);
    if (n == 30 && hdr[0] == 'P' && hdr[1] == 'K' && hdr[2] == 3 && hdr[3] == 4) {
        unsigned method = hdr[8] | (hdr[9] << 8);
        if (method == 8) {
            zo.was_deflated_zip = 1;
            uint32_t usize = (uint32_t)hdr[22] | ((uint32_t)hdr[23] << 8) |
                             ((uint32_t)hdr[24] << 16) | ((uint32_t)hdr[25] << 24);
            unsigned namelen = hdr[26] | (hdr[27] << 8);
            unsigned extralen = hdr[28] | (hdr[29] << 8);
            int fail = 0;
            for (unsigned i = 0; i < namelen + extralen; i++) {
                if (fgetc(raw) == EOF) { fail = 1; break; }
            }
            unsigned char *comp = NULL;
            size_t complen = 0, compcap = 0;
            if (!fail) {
                for (;;) {
                    if (complen == compcap) {
                        compcap = compcap ? compcap * 2 : 8192;
                        comp = xrealloc(comp, compcap);
                    }
                    size_t r = fread(comp + complen, 1, compcap - complen, raw);
                    complen += r;
                    if (r == 0) break;
                }
            }
            fclose(raw);
            unsigned char *out = xmalloc(usize ? usize : 1);
            int ok = 0;
            if (!fail && comp) {
                if (inflate_raw(comp, complen, out, usize) == 0) ok = 1;
            }
            if (comp) free(comp);
            if (!ok) {
                free(out);
                zo.fp = tmpfile();
                return zo;
            }
            keep_zip_buffer(out);
            if (usize == 0) {
                zo.fp = tmpfile();
            } else {
                zo.fp = fmemopen(out, usize, "rb");
                if (!zo.fp) zo.fp = tmpfile();
            }
            return zo;
        }
    }
    /* plain: rewind */
    if (n > 0) {
        if (fseek(raw, 0, SEEK_SET) != 0) {
            /* Non-seekable inputs are not expected for font/control files;
               data already read would be lost, as in a simple rewind model. */
        }
    }
    zo.fp = raw;
    return zo;
}

