/* ---------- font data ---------- */
typedef struct {
    long code;
    wchar_t **rows;
    int width;
} Glyph;
static Glyph *glyphs = NULL;
static size_t nglyphs = 0, glyphs_cap = 0;
static int charheight = 1;
static wchar_t hardblank = L'$';
static Glyph *lookup_glyph(long code) {
    for (size_t i = 0; i < nglyphs; i++)
        if (glyphs[i].code == code) return &glyphs[i];
    return NULL;
}
static void free_glyph_rows(Glyph *g) {
    if (g->rows) {
        for (int i = 0; i < charheight; i++) free(g->rows[i]);
        free(g->rows);
        g->rows = NULL;
    }
}
static void store_glyph(long code, wchar_t **rows, int width) {
    Glyph *old = lookup_glyph(code);
    if (old) {
        free_glyph_rows(old);
        old->rows = rows; old->width = width;
        return;
    }
    if (nglyphs == glyphs_cap) {
        glyphs_cap = glyphs_cap ? glyphs_cap * 2 : 256;
        glyphs = xrealloc(glyphs, glyphs_cap * sizeof(*glyphs));
    }
    glyphs[nglyphs].code = code;
    glyphs[nglyphs].rows = rows;
    glyphs[nglyphs].width = width;
    nglyphs++;
}
static wchar_t *wdup_n(const wchar_t *s, size_t n) {
    wchar_t *p = xmalloc((n + 1) * sizeof(wchar_t));
    if (n) memcpy(p, s, n * sizeof(wchar_t));
    p[n] = L'\0';
    return p;
}
static wchar_t *wdup(const wchar_t *s) { return wdup_n(s, wcslen(s)); }

static FILE *open_font_file(const char **selected_ext) {
    static const char *exts[2] = {".flf", ".tlf"};
    for (int ei = 0; ei < 2; ei++) {
        const char *ext = exts[ei];
        char *path = NULL;
        if (strchr(fontname, '/') != NULL) {
            path = concat2(fontname, ext);
        } else {
            char *dirpath = concat3(fontdir, "/", fontname);
            char *dirfull = concat2(dirpath, ext);
            free(dirpath);
            struct stat st;
            if (stat(dirfull, &st) == 0) path = dirfull;
            else { free(dirfull); path = concat2(fontname, ext); }
        }
        ZOpen zo = zopen_path(path);
        free(path);
        if (zo.fp) { *selected_ext = ext; return zo.fp; }
    }
