/* Shared conversion buffer for glyph rows (see investigation notes). */
static wchar_t *convbuf = NULL;
static size_t convcap = 0;
static wchar_t *convert_glyph_line(const char *line) {
    size_t need = strlen(line) + 2;
    if (!convbuf) {
        convcap = 8192;
        if (need > convcap) convcap = need;
        convbuf = xcalloc(convcap, sizeof(wchar_t));
    } else if (need > convcap) {
        size_t old = convcap;
        while (convcap < need) convcap *= 2;
        convbuf = xrealloc(convbuf, convcap * sizeof(wchar_t));
        memset(convbuf + old, 0, (convcap - old) * sizeof(wchar_t));
    }
    (void)mbstowcs(convbuf, line, convcap - 1);
    size_t len = wcslen(convbuf);
    while (len > 0) {
        wchar_t c = convbuf[len - 1];
        if (c == L' ' || c == L'\t' || c == L'\n' || c == L'\v' || c == L'\f' || c == L'\r') len--;
        else break;
    }
    if (len > 0) {
        wchar_t endmark = convbuf[len - 1];
        while (len > 0 && convbuf[len - 1] == endmark) len--;
    }
    convbuf[len] = L'\0';
    return wdup_n(convbuf, len);
}
static int font_eof_flag = 0;
static wchar_t **read_figchar(FILE *fp, char **linebuf, size_t *linecap) {
    wchar_t **rows = xcalloc((size_t)charheight, sizeof(wchar_t *));
    for (int i = 0; i < charheight; i++) {
        if (font_eof_flag) { rows[i] = wdup(L""); continue; }
        ssize_t r = getline(linebuf, linecap, fp);
        if (r < 0) {
            font_eof_flag = 1;
            if (convbuf) convbuf[0] = L'\0';
            rows[i] = wdup(L"");
        } else {
            rows[i] = convert_glyph_line(*linebuf);
        }
    }
    return rows;
}
static void load_font(void) {
    const char *ext = NULL;
