    if (!fp) {
        fprintf(stderr, "%s: %s: Unable to open font file\n", progname, fontname);
        exit(1);
    }
    const char *sig = (ext && strcmp(ext, ".tlf") == 0) ? "tlf2" : "flf2";
    char *line = NULL;
    size_t linecap = 0;
    ssize_t r = getline(&line, &linecap, fp);
    if (r < 0) { fclose(fp); font_error_notfont(); }
    int height = 0, baseline = 0, maxlen = 0, oldlayout = 0, comments = 0;
    int printdir = 0, fulllayout = 0, codetagcount = 0;
    (void)baseline; (void)maxlen; (void)codetagcount;
    int nfields = 0;
    if (strlen(line) >= 6) {
        nfields = sscanf(line + 6, "%d %d %d %d %d %d %d %d",
                         &height, &baseline, &maxlen, &oldlayout, &comments,
                         &printdir, &fulllayout, &codetagcount);
    }
    if (strncmp(line, sig, 4) != 0 || nfields < 5) {
        fclose(fp);
        font_error_notfont();
    }
    hardblank = (wchar_t)(unsigned char)line[5];
    font_printdir = (nfields >= 6) ? printdir : 0;
    charheight = height < 1 ? 1 : height;
    if (nfields >= 7) {
        int h = fulllayout & 0xFF;
        if (h & 128) {
            if (h & 63) { font_smush_kind = SM_CONTROLLED; font_smush_mask = h & 63; }
            else font_smush_kind = SM_UNIVERSAL;
        } else if (h & 64) font_smush_kind = SM_KERN;
        else font_smush_kind = SM_FULL;
    } else {
        if (oldlayout < 0) font_smush_kind = SM_FULL;
        else if (oldlayout == 0) font_smush_kind = SM_KERN;
        else if (oldlayout & 63) { font_smush_kind = SM_CONTROLLED; font_smush_mask = oldlayout & 63; }
        else font_smush_kind = SM_UNIVERSAL;
    }
    font_eof_flag = 0;
    for (int i = 0; i < comments; i++) {
        if (getline(&line, &linecap, fp) < 0) { font_eof_flag = 1; break; }
    }
    for (int code = 32; code <= 126; code++) {
        wchar_t **rows = read_figchar(fp, &line, &linecap);
        store_glyph(code, rows, (int)wcslen(rows[0]));
    }
    static const long deutsch_codes[7] = {196, 214, 220, 228, 246, 252, 223};
    for (int i = 0; i < 7; i++) {
        wchar_t **rows = read_figchar(fp, &line, &linecap);
        store_glyph(deutsch_codes[i], rows, (int)wcslen(rows[0]));
    }
    while (!font_eof_flag) {
        ssize_t rr = getline(&line, &linecap, fp);
        if (rr < 0) break;
        char *endp = NULL;
        long code = strtol(line, &endp, 0);
        if (endp == line) break;
        wchar_t **rows = read_figchar(fp, &line, &linecap);
        store_glyph(code, rows, (int)wcslen(rows[0]));
    }
    free(line);
    fclose(fp);
}

