/* The unusual FIGlet numeral parser used in control files. */
static long parse_fig_number(char **pp, int *consumed_any) {
    char *p = *pp;
    long sign = 1;
    unsigned long val = 0;
    int any = 0;
    if (*p == '-') { sign = -1; p++; }
    int base = 10;
    if (*p == '0') {
        any = 1;
        if (p[1] == 'x' || p[1] == 'X') { base = 16; p += 2; }
        else { base = 8; p++; }
    }
    while (isxdigit((unsigned char)*p)) {
        int digit;
        if (isdigit((unsigned char)*p)) digit = *p - '0';
        else digit = ascii_tolower((unsigned char)*p) - 'a' + 10;
        val = val * (unsigned long)base + (unsigned long)digit;
        p++;
        any = 1;
    }
    if (consumed_any) *consumed_any = any;
    *pp = p;
    if (sign < 0) return -(long)val;
    return (long)val;
}
static long read_char_spec(char **pp, int skip_spaces, int *ok) {
    char *p = *pp;
