static int hier_class(wchar_t c) {
    if (c == L'|') return 0;
    if (c == L'/' || c == L'\\') return 1;
    if (c == L'[' || c == L']') return 2;
    if (c == L'{' || c == L'}') return 3;
    if (c == L'(' || c == L')') return 4;
    if (c == L'<' || c == L'>') return 5;
    return -1;
