static int smush_pair(wchar_t l, wchar_t r, wchar_t *out) {
    if (l == L' ') { *out = r; return 1; }
    if (r == L' ') { *out = l; return 1; }
    if (smush_kind == SM_UNIVERSAL) {
        *out = (r == hardblank) ? l : r;
        return 1;
    }
    if (smush_kind != SM_CONTROLLED) {
        /* Kern/full: only space-involving pairs are expected to overlap.
           If a non-space pair is forced to overlap, prefer the right char. */
        *out = r;
        return 0;
    }
    int mask = smush_mask;
    if (l == hardblank || r == hardblank) {
        if ((mask & 32) && l == hardblank && r == hardblank) { *out = hardblank; return 1; }
        return 0;
    }
    if ((mask & 1) && l == r) { *out = l; return 1; }
    if ((mask & 2) && (l == L'_' || r == L'_')) {
        wchar_t other = (l == L'_') ? r : l;
        const wchar_t *set = L"|/\\[]{}()<>";
        for (const wchar_t *p = set; *p; p++) if (*p == other) { *out = other; return 1; }
    }
    if (mask & 8) {
        if (((l == L'[' && r == L']') || (l == L']' && r == L'[') ||
             (l == L'{' && r == L'}') || (l == L'}' && r == L'{') ||
             (l == L'(' && r == L')') || (l == L')' && r == L'('))) {
            *out = L'|'; return 1;
