    if (mask & 16) {
        if (l == L'/' && r == L'\\') { *out = L'|'; return 1; }
        if (l == L'\\' && r == L'/') { *out = L'Y'; return 1; }
        if (l == L'>' && r == L'<') { *out = L'X'; return 1; }
    }
    if (mask & 4) {
        int cl = hier_class(l), cr = hier_class(r);
        if (cl >= 0 && cr >= 0 && cl != cr) { *out = (cl > cr) ? l : r; return 1; }
    }
