    for (int i = 0; i < charheight; i++) {
        const wchar_t *lrow = resolved_direction ? g->rows[i] : out->rows[i];
        const wchar_t *rrow = resolved_direction ? out->rows[i] : g->rows[i];
        size_t llen = wcslen(lrow), rlen = wcslen(rrow);
        size_t trail = 0;
        while (trail < llen && lrow[llen - 1 - trail] == L' ') trail++;
        size_t lead = 0;
        while (lead < rlen && rrow[lead] == L' ') lead++;
        int cand = (int)(trail + lead);
        if (smush_kind == SM_UNIVERSAL || smush_kind == SM_CONTROLLED) {
