static void add_glyph_ltr(OutputLine *out, const Glyph *g, int amount) {
    for (int i = 0; i < charheight; i++) {
        wchar_t *oldrow = out->rows[i];
        const wchar_t *grow = g->rows[i];
        size_t oldlen = wcslen(oldrow), glen = wcslen(grow);
        long start = (long)oldlen - amount;
        size_t gskip = 0;
        if (start < 0) { gskip = (size_t)(-start); start = 0; }
        if (gskip >= glen) continue;
        size_t need = (size_t)start + (glen - gskip);
        size_t newlen = oldlen > need ? oldlen : need;
        wchar_t *newrow = xmalloc((newlen + 1) * sizeof(wchar_t));
        for (size_t j = 0; j < newlen; j++) newrow[j] = L' ';
        if (oldlen) memcpy(newrow, oldrow, oldlen * sizeof(wchar_t));
        for (size_t j = gskip; j < glen; j++) {
            size_t pos = (size_t)start + (j - gskip);
            if (pos < oldlen) newrow[pos] = overlay_pair(oldrow[pos], grow[j]);
            else newrow[pos] = grow[j];
        }
        newrow[newlen] = L'\0';
        free(oldrow);
        out->rows[i] = newrow;
