static void add_glyph_rtl(OutputLine *out, const Glyph *g, int amount) {
    int was_empty = !out->has_any;
    for (int i = 0; i < charheight; i++) {
        wchar_t *oldrow = out->rows[i];
        const wchar_t *grow = g->rows[i];
        if (was_empty) {
            free(oldrow);
            out->rows[i] = wdup(grow);
            continue;
        }
        size_t oldlen = wcslen(oldrow), glen = wcslen(grow);
        long off = (long)glen - amount;
        size_t oskip = 0;
        if (off < 0) { oskip = (size_t)(-off); off = 0; }
        if (oskip > oldlen) oskip = oldlen;
        size_t need = (size_t)off + (oldlen - oskip);
        size_t newlen = glen > need ? glen : need;
        wchar_t *newrow = xmalloc((newlen + 1) * sizeof(wchar_t));
        for (size_t j = 0; j < newlen; j++) newrow[j] = L' ';
        if (glen) memcpy(newrow, grow, glen * sizeof(wchar_t));
        for (size_t j = oskip; j < oldlen; j++) {
            size_t pos = (size_t)off + (j - oskip);
            if (pos < glen) newrow[pos] = overlay_pair(grow[pos], oldrow[j]);
            else newrow[pos] = oldrow[j];
