static void output_wchar_utf8(wchar_t wc) {
    unsigned long c = (unsigned long)wc;
    if (wc == hardblank) { putchar(' '); return; }
    if (c < 0x80) {
        putchar((int)c);
    } else if (c < 0x800) {
        putchar(0xC0 | (c >> 6)); putchar(0x80 | (c & 0x3F));
    } else if (c < 0x10000) {
        putchar(0xE0 | (c >> 12)); putchar(0x80 | ((c >> 6) & 0x3F)); putchar(0x80 | (c & 0x3F));
    } else if (c < 0x200000) {
        putchar(0xF0 | (c >> 18)); putchar(0x80 | ((c >> 12) & 0x3F));
        putchar(0x80 | ((c >> 6) & 0x3F)); putchar(0x80 | (c & 0x3F));
    } else if (c < 0x4000000) {
        putchar(0xF8 | (c >> 24)); putchar(0x80 | ((c >> 18) & 0x3F));
        putchar(0x80 | ((c >> 12) & 0x3F)); putchar(0x80 | ((c >> 6) & 0x3F));
        putchar(0x80 | (c & 0x3F));
    } else {
        putchar(0xFC | (c >> 30)); putchar(0x80 | ((c >> 24) & 0x3F));
        putchar(0x80 | ((c >> 18) & 0x3F)); putchar(0x80 | ((c >> 12) & 0x3F));
        putchar(0x80 | ((c >> 6) & 0x3F)); putchar(0x80 | (c & 0x3F));
    }
