static void print_output_line(OutputLine *out) {
    for (int i = 0; i < charheight; i++) {
        wchar_t *row = out->rows[i];
        size_t len = wcslen(row);
        size_t start = 0;
        size_t plen = len;
        if (outputwidth != 1) {
            size_t limit = (size_t)(outputwidth - 1);
            if (plen > limit) {
                if (resolved_direction) start = plen - limit;
                plen = limit;
            }
        }
        long offset = 0;
        if (resolved_justification == 1) {
            if ((long)len < outputwidth) offset = (outputwidth - (long)len) / 2;
        } else if (resolved_justification == 2) {
            if ((long)len < outputwidth) offset = outputwidth - (long)len - 1;
        }
        if (offset < 0) offset = 0;
        for (long j = 0; j < offset; j++) putchar(' ');
        for (size_t j = 0; j < plen; j++) output_wchar_utf8(row[start + j]);
        putchar('\n');
    }
}

typedef struct { Glyph *g; int is_space; } Item;

static void render_logical_line(Item *items, size_t nitems, int explicit_newline) {
    OutputLine cur, snapshot;
    out_init(&cur);
    out_init(&snapshot);
    int snapshot_valid = 0;
    Glyph **curword = NULL;
    size_t curword_n = 0, curword_cap = 0;
    int in_space_run = 0;
    int discard_spaces = 0;
    int segments = 0;
    int limit = (outputwidth == 1) ? 0 : outputwidth - 1;
#define PUSH_CURWORD(gg) do { \
    if (curword_n == curword_cap) { curword_cap = curword_cap ? curword_cap * 2 : 16; \
        curword = xrealloc(curword, curword_cap * sizeof(*curword)); } \
    curword[curword_n++] = (gg); } while (0)
#define ADD_WITHIN_WORD(gg) do { \
    const Glyph *_g = (gg); \
    int _amt = compute_amount(&cur, _g); \
    if (cur.has_any && cur.outlen + _g->width - _amt > limit) { \
        print_output_line(&cur); segments++; out_clear(&cur); curword_n = 0; snapshot_valid = 0; \
        _amt = compute_amount(&cur, _g); \
    } \
    add_glyph(&cur, _g, _amt); PUSH_CURWORD((Glyph *)_g); } while (0)

    for (size_t idx = 0; idx < nitems; idx++) {
        Glyph *g = items[idx].g;
        int is_space = items[idx].is_space;
        if (is_space && discard_spaces) continue;
        if (!is_space) discard_spaces = 0;
        if (is_space) {
            if (!in_space_run) {
                if (curword_n > 0) {
                    out_clone(&snapshot, &cur);
                    snapshot_valid = 1;
                    curword_n = 0;
                }
                in_space_run = 1;
            }
            int amt = compute_amount(&cur, g);
            if (cur.has_any && cur.outlen + g->width - amt > limit) {
                if (snapshot_valid) print_output_line(&snapshot);
                else print_output_line(&cur);
                segments++;
                out_clear(&cur);
                snapshot_valid = 0;
                curword_n = 0;
                in_space_run = 0;
                discard_spaces = 1;
                continue;
            }
            add_glyph(&cur, g, amt);
        } else {
            in_space_run = 0;
            int amt = compute_amount(&cur, g);
            if (cur.has_any && cur.outlen + g->width - amt > limit) {
                if (snapshot_valid) {
                    /* Save the current word (glyphs after the breaking space). */
                    size_t saved_n = curword_n;
                    Glyph **saved = NULL;
                    if (saved_n) {
                        saved = xmalloc(saved_n * sizeof(*saved));
                        memcpy(saved, curword, saved_n * sizeof(*saved));
                    }
                    print_output_line(&snapshot);
                    segments++;
                    out_clear(&cur);
                    snapshot_valid = 0;
                    curword_n = 0;
                    for (size_t k = 0; k < saved_n; k++) {
                        Glyph *sg = saved[k];
                        ADD_WITHIN_WORD(sg);
                    }
                    free(saved);
                    ADD_WITHIN_WORD(g);
                } else {
                    print_output_line(&cur);
                    segments++;
                    out_clear(&cur);
                    curword_n = 0;
                    ADD_WITHIN_WORD(g);
                }
            } else {
                add_glyph(&cur, g, amt);
                PUSH_CURWORD(g);
            }
