    }
#undef ADD_WITHIN_WORD
#undef PUSH_CURWORD
    if (cur.has_any || (explicit_newline && segments == 0)) {
        print_output_line(&cur);
    }
    free(curword);
    out_free(&cur);
    out_free(&snapshot);
}

/* ---------- main ---------- */
static void resolve_modes(void) {
    if (direction_opt >= 0) resolved_direction = direction_opt;
    else resolved_direction = (font_printdir != 0) ? 1 : 0;
    if (justification == 3) resolved_justification = resolved_direction ? 2 : 0;
    else resolved_justification = justification;
    switch (user_smush) {
        case US_DEFAULT:
            smush_kind = font_smush_kind; smush_mask = font_smush_mask; break;
        case US_FORCE_SMUSH:
            if (font_smush_kind == SM_FULL || font_smush_kind == SM_KERN) smush_kind = SM_UNIVERSAL;
            else { smush_kind = font_smush_kind; smush_mask = font_smush_mask; }
            break;
        case US_UNIVERSAL: smush_kind = SM_UNIVERSAL; break;
        case US_KERN: smush_kind = SM_KERN; break;
        case US_FULL: smush_kind = SM_FULL; break;
        case US_EXPLICIT:
            if (user_smush_mask & 63) { smush_kind = SM_CONTROLLED; smush_mask = user_smush_mask & 63; }
