    }
}
static int query_terminal_width(void) {
    int fd = open("/dev/tty", O_RDONLY);
    if (fd < 0) return 0;
    struct winsize ws;
    int cols = 0;
    if (ioctl(fd, TIOCGWINSZ, &ws) == 0) cols = ws.ws_col;
    close(fd);
    return cols;
}

int main(int argc, char **argv) {
    const char *argv0 = (argc > 0 && argv[0]) ? argv[0] : "";
    const char *slash = strrchr(argv0, '/');
    progname = slash ? slash + 1 : argv0;
    (void)setlocale(LC_CTYPE, "C.UTF-8");
