            case 'c': justification = 1; break;
            case 'l': justification = 0; break;
            case 'r': justification = 2; break;
            case 'x': justification = 3; break;
            case 'L': direction_opt = 0; break;
            case 'R': direction_opt = 1; break;
            case 'X': direction_opt = -1; break;
            case 'p': paragraph_mode = 1; break;
            case 'n': paragraph_mode = 0; break;
            case 'D': deutsch_mode = 1; break;
            case 'E': deutsch_mode = 0; break;
            case 's': user_smush = US_DEFAULT; break;
            case 'S': user_smush = US_FORCE_SMUSH; break;
            case 'k': user_smush = US_KERN; break;
            case 'W': user_smush = US_FULL; break;
            case 'o': user_smush = US_UNIVERSAL; break;
            case 'A': break;
            case 't': {
                int col = query_terminal_width();
                if (col > 0) outputwidth = col;
                break;
            }
            case 'w': {
                int v = atoi(optarg);
                if (v > 0) outputwidth = v;
                break;
            }
            case 'm': {
                int v = atoi(optarg);
                if (v <= -2) user_smush = US_DEFAULT;
                else if (v == -1) user_smush = US_FULL;
                else if (v == 0) user_smush = US_KERN;
                else { user_smush = US_EXPLICIT; user_smush_mask = v; }
                break;
            }
            case 'd': fontdir = optarg; break;
            case 'f': free(fontname); fontname = strip_font_suffix(optarg); break;
            case 'C': {
                if (ncontrols == controls_cap) {
