                ncontrols = 0;
                break;
            case 'v': infocode = 0; break;
            case 'I': infocode = atoi(optarg); break;
            case 'F':
                fprintf(stderr, "%s: illegal option -- F\n", progname);
                print_usage(stderr);
                fprintf(stderr, "\n");
                fprintf(stderr, "Because of numerous incompatibilities, the \"-F\" option has been\n");
                fprintf(stderr, "removed.  It has been replaced by the \"figlist\" program, which is now\n");
                fprintf(stderr, "included in the basic FIGlet package.  \"figlist\" is also available\n");
                fprintf(stderr, "from  http://www.figlet.org/under UNIX utilities.\n");
                return 1;
            case '?':
            default:
                print_usage(stderr);
                return 1;
        }
    }
    if (infocode >= 0) {
        switch (infocode) {
            case 0: print_version(); break;
            case 1: printf("20205\n"); break;
            case 2: printf("%s\n", fontdir); break;
            case 3: printf("%s\n", fontname); break;
            case 4: printf("%d\n", outputwidth); break;
