        int cand = (int)(trail + lead);
        if (smush_kind == SM_UNIVERSAL || smush_kind == SM_CONTROLLED) {
            if (trail < llen && lead < rlen && out->last_width > 1 && g->width > 1) {
                wchar_t combined;
                if (smush_pair(lrow[llen - 1 - trail], rrow[lead], &combined)) cand++;
            }
        }
        if (cand < amount) amount = cand;
    }
    return amount;
}
static wchar_t overlay_pair(wchar_t oldc, wchar_t newc) {
    wchar_t outc;
    if (oldc == L' ') return newc;
    if (newc == L' ') return oldc;
    if (smush_pair(oldc, newc, &outc)) return outc;
    return newc;
}
static void add_glyph_ltr(OutputLine *out, const Glyph *g, int amount) {
    for (int i = 0; i < charheight; i++) {
        wchar_t *oldrow = out->rows[i];
        const wchar_t *grow = g->rows[i];
        size_t oldlen = wcslen(oldrow), glen = wcslen(grow);
        long start = (long)oldlen - amount;
        size_t gskip = 0;
        if (start < 0) { gskip = (size_t)(-start); start = 0; }
        if (gskip >= glen) continue;
        size_t need = (size_t)start + (glen - gskip);
        size_t newlen = oldlen > need ? oldlen : need;
        wchar_t *newrow = xmalloc((newlen + 1) * sizeof(wchar_t));
        for (size_t j = 0; j < newlen; j++) newrow[j] = L' ';
        if (oldlen) memcpy(newrow, oldrow, oldlen * sizeof(wchar_t));
        for (size_t j = gskip; j < glen; j++) {
            size_t pos = (size_t)start + (j - gskip);
            if (pos < oldlen) newrow[pos] = overlay_pair(oldrow[pos], grow[j]);
            else newrow[pos] = grow[j];
        }
        newrow[newlen] = L'\0';
        free(oldrow);
        out->rows[i] = newrow;
    }
    out->outlen += g->width - amount;
    out->last_width = g->width;
    out->has_any = 1;
}
static void add_glyph_rtl(OutputLine *out, const Glyph *g, int amount) {
    int was_empty = !out->has_any;
    for (int i = 0; i < charheight; i++) {
        wchar_t *oldrow = out->rows[i];
        const wchar_t *grow = g->rows[i];
        if (was_empty) {
            free(oldrow);
            out->rows[i] = wdup(grow);
            continue;
        }
        size_t oldlen = wcslen(oldrow), glen = wcslen(grow);
        long off = (long)glen - amount;
        size_t oskip = 0;
        if (off < 0) { oskip = (size_t)(-off); off = 0; }
        if (oskip > oldlen) oskip = oldlen;
        size_t need = (size_t)off + (oldlen - oskip);
        size_t newlen = glen > need ? glen : need;
        wchar_t *newrow = xmalloc((newlen + 1) * sizeof(wchar_t));
        for (size_t j = 0; j < newlen; j++) newrow[j] = L' ';
        if (glen) memcpy(newrow, grow, glen * sizeof(wchar_t));
        for (size_t j = oskip; j < oldlen; j++) {
            size_t pos = (size_t)off + (j - oskip);
            if (pos < glen) newrow[pos] = overlay_pair(grow[pos], oldrow[j]);
            else newrow[pos] = oldrow[j];
        }
        newrow[newlen] = L'\0';
        free(oldrow);
        out->rows[i] = newrow;
    }
    out->outlen += g->width - amount;
    out->last_width = g->width;
    out->has_any = 1;
}
static void add_glyph(OutputLine *out, const Glyph *g, int amount) {
    if (resolved_direction) add_glyph_rtl(out, g, amount);
    else add_glyph_ltr(out, g, amount);
}
static void output_wchar_utf8(wchar_t wc) {
    unsigned long c = (unsigned long)wc;
    if (wc == hardblank) { putchar(' '); return; }
    if (c < 0x80) {
        putchar((int)c);
    } else if (c < 0x800) {
        putchar(0xC0 | (c >> 6)); putchar(0x80 | (c & 0x3F));
    } else if (c < 0x10000) {
        putchar(0xE0 | (c >> 12)); putchar(0x80 | ((c >> 6) & 0x3F)); putchar(0x80 | (c & 0x3F));
    } else if (c < 0x200000) {
        putchar(0xF0 | (c >> 18)); putchar(0x80 | ((c >> 12) & 0x3F));
        putchar(0x80 | ((c >> 6) & 0x3F)); putchar(0x80 | (c & 0x3F));
    } else if (c < 0x4000000) {
        putchar(0xF8 | (c >> 24)); putchar(0x80 | ((c >> 18) & 0x3F));
        putchar(0x80 | ((c >> 12) & 0x3F)); putchar(0x80 | ((c >> 6) & 0x3F));
        putchar(0x80 | (c & 0x3F));
    } else {
        putchar(0xFC | (c >> 30)); putchar(0x80 | ((c >> 24) & 0x3F));
        putchar(0x80 | ((c >> 18) & 0x3F)); putchar(0x80 | ((c >> 12) & 0x3F));
        putchar(0x80 | ((c >> 6) & 0x3F)); putchar(0x80 | (c & 0x3F));
    }
}
static void print_output_line(OutputLine *out) {
    for (int i = 0; i < charheight; i++) {
        wchar_t *row = out->rows[i];
        size_t len = wcslen(row);
        size_t start = 0;
        size_t plen = len;
        if (outputwidth != 1) {
            size_t limit = (size_t)(outputwidth - 1);
            if (plen > limit) {
                if (resolved_direction) start = plen - limit;
                plen = limit;
            }
        }
        long offset = 0;
        if (resolved_justification == 1) {
            if ((long)len < outputwidth) offset = (outputwidth - (long)len) / 2;
        } else if (resolved_justification == 2) {
            if ((long)len < outputwidth) offset = outputwidth - (long)len - 1;
        }
        if (offset < 0) offset = 0;
        for (long j = 0; j < offset; j++) putchar(' ');
        for (size_t j = 0; j < plen; j++) output_wchar_utf8(row[start + j]);
        putchar('\n');
    }
}

typedef struct { Glyph *g; int is_space; } Item;

static void render_logical_line(Item *items, size_t nitems, int explicit_newline) {
    OutputLine cur, snapshot;
    out_init(&cur);
    out_init(&snapshot);
    int snapshot_valid = 0;
    Glyph **curword = NULL;
    size_t curword_n = 0, curword_cap = 0;
    int in_space_run = 0;
    int discard_spaces = 0;
    int segments = 0;
    int limit = (outputwidth == 1) ? 0 : outputwidth - 1;
#define PUSH_CURWORD(gg) do { \
    if (curword_n == curword_cap) { curword_cap = curword_cap ? curword_cap * 2 : 16; \
        curword = xrealloc(curword, curword_cap * sizeof(*curword)); } \
    curword[curword_n++] = (gg); } while (0)
#define ADD_WITHIN_WORD(gg) do { \
    const Glyph *_g = (gg); \
    int _amt = compute_amount(&cur, _g); \
    if (cur.has_any && cur.outlen + _g->width - _amt > limit) { \
        print_output_line(&cur); segments++; out_clear(&cur); curword_n = 0; snapshot_valid = 0; \
        _amt = compute_amount(&cur, _g); \
    } \
    add_glyph(&cur, _g, _amt); PUSH_CURWORD((Glyph *)_g); } while (0)

    for (size_t idx = 0; idx < nitems; idx++) {
        Glyph *g = items[idx].g;
        int is_space = items[idx].is_space;
        if (is_space && discard_spaces) continue;
        if (!is_space) discard_spaces = 0;
        if (is_space) {
            if (!in_space_run) {
                if (curword_n > 0) {
                    out_clone(&snapshot, &cur);
                    snapshot_valid = 1;
                    curword_n = 0;
                }
                in_space_run = 1;
            }
            int amt = compute_amount(&cur, g);
            if (cur.has_any && cur.outlen + g->width - amt > limit) {
                if (snapshot_valid) print_output_line(&snapshot);
                else print_output_line(&cur);
                segments++;
                out_clear(&cur);
                snapshot_valid = 0;
                curword_n = 0;
                in_space_run = 0;
                discard_spaces = 1;
                continue;
            }
            add_glyph(&cur, g, amt);
        } else {
            in_space_run = 0;
            int amt = compute_amount(&cur, g);
            if (cur.has_any && cur.outlen + g->width - amt > limit) {
                if (snapshot_valid) {
                    /* Save the current word (glyphs after the breaking space). */
                    size_t saved_n = curword_n;
                    Glyph **saved = NULL;
                    if (saved_n) {
                        saved = xmalloc(saved_n * sizeof(*saved));
                        memcpy(saved, curword, saved_n * sizeof(*saved));
                    }
                    print_output_line(&snapshot);
                    segments++;
                    out_clear(&cur);
                    snapshot_valid = 0;
                    curword_n = 0;
                    for (size_t k = 0; k < saved_n; k++) {
                        Glyph *sg = saved[k];
                        ADD_WITHIN_WORD(sg);
                    }
                    free(saved);
                    ADD_WITHIN_WORD(g);
                } else {
                    print_output_line(&cur);
                    segments++;
                    out_clear(&cur);
                    curword_n = 0;
                    ADD_WITHIN_WORD(g);
                }
            } else {
                add_glyph(&cur, g, amt);
                PUSH_CURWORD(g);
            }
        }
    }
#undef ADD_WITHIN_WORD
#undef PUSH_CURWORD
    if (cur.has_any || (explicit_newline && segments == 0)) {
        print_output_line(&cur);
    }
    free(curword);
    out_free(&cur);
    out_free(&snapshot);
}

/* ---------- main ---------- */
static void resolve_modes(void) {
    if (direction_opt >= 0) resolved_direction = direction_opt;
    else resolved_direction = (font_printdir != 0) ? 1 : 0;
    if (justification == 3) resolved_justification = resolved_direction ? 2 : 0;
    else resolved_justification = justification;
    switch (user_smush) {
        case US_DEFAULT:
            smush_kind = font_smush_kind; smush_mask = font_smush_mask; break;
        case US_FORCE_SMUSH:
            if (font_smush_kind == SM_FULL || font_smush_kind == SM_KERN) smush_kind = SM_UNIVERSAL;
            else { smush_kind = font_smush_kind; smush_mask = font_smush_mask; }
            break;
        case US_UNIVERSAL: smush_kind = SM_UNIVERSAL; break;
        case US_KERN: smush_kind = SM_KERN; break;
        case US_FULL: smush_kind = SM_FULL; break;
        case US_EXPLICIT:
            if (user_smush_mask & 63) { smush_kind = SM_CONTROLLED; smush_mask = user_smush_mask & 63; }
            else smush_kind = SM_UNIVERSAL;
            break;
    }
}
static int query_terminal_width(void) {
    int fd = open("/dev/tty", O_RDONLY);
    if (fd < 0) return 0;
    struct winsize ws;
    int cols = 0;
    if (ioctl(fd, TIOCGWINSZ, &ws) == 0) cols = ws.ws_col;
    close(fd);
    return cols;
}

int main(int argc, char **argv) {
    const char *argv0 = (argc > 0 && argv[0]) ? argv[0] : "";
    const char *slash = strrchr(argv0, '/');
    progname = slash ? slash + 1 : argv0;
    (void)setlocale(LC_CTYPE, "C.UTF-8");
    init_decoder_config();
    {
        const char *envdir = getenv("FIGLET_FONTDIR");
        if (envdir) fontdir = envdir;
    }
    fontname = xstrdup("standard");
    char **controls = NULL;
    size_t ncontrols = 0, controls_cap = 0;
    static const char optstring[] = "cklnoprstvxAC:DEFI:LNRSWXD:d:f:m:w:E";
    /* Note: the duplicated-ish string above is assembled so that every
       documented option is present; getopt only cares about membership. */
    int opt;
    while ((opt = getopt(argc, argv, optstring)) != -1) {
        switch (opt) {
            case 'c': justification = 1; break;
            case 'l': justification = 0; break;
            case 'r': justification = 2; break;
            case 'x': justification = 3; break;
            case 'L': direction_opt = 0; break;
            case 'R': direction_opt = 1; break;
            case 'X': direction_opt = -1; break;
            case 'p': paragraph_mode = 1; break;
            case 'n': paragraph_mode = 0; break;
            case 'D': deutsch_mode = 1; break;
            case 'E': deutsch_mode = 0; break;
            case 's': user_smush = US_DEFAULT; break;
            case 'S': user_smush = US_FORCE_SMUSH; break;
            case 'k': user_smush = US_KERN; break;
            case 'W': user_smush = US_FULL; break;
            case 'o': user_smush = US_UNIVERSAL; break;
            case 'A': break;
            case 't': {
                int col = query_terminal_width();
                if (col > 0) outputwidth = col;
                break;
            }
            case 'w': {
                int v = atoi(optarg);
                if (v > 0) outputwidth = v;
                break;
            }
            case 'm': {
                int v = atoi(optarg);
                if (v <= -2) user_smush = US_DEFAULT;
                else if (v == -1) user_smush = US_FULL;
                else if (v == 0) user_smush = US_KERN;
                else { user_smush = US_EXPLICIT; user_smush_mask = v; }
                break;
            }
            case 'd': fontdir = optarg; break;
            case 'f': free(fontname); fontname = strip_font_suffix(optarg); break;
            case 'C': {
                if (ncontrols == controls_cap) {
                    controls_cap = controls_cap ? controls_cap * 2 : 8;
                    controls = xrealloc(controls, controls_cap * sizeof(*controls));
                }
                controls[ncontrols++] = strip_control_suffix(optarg);
                break;
            }
            case 'N':
                for (size_t i = 0; i < ncontrols; i++) free(controls[i]);
                ncontrols = 0;
                break;
            case 'v': infocode = 0; break;
            case 'I': infocode = atoi(optarg); break;
            case 'F':
                fprintf(stderr, "%s: illegal option -- F\n", progname);
                print_usage(stderr);
                fprintf(stderr, "\n");
                fprintf(stderr, "Because of numerous incompatibilities, the \"-F\" option has been\n");
                fprintf(stderr, "removed.  It has been replaced by the \"figlist\" program, which is now\n");
                fprintf(stderr, "included in the basic FIGlet package.  \"figlist\" is also available\n");
                fprintf(stderr, "from  http://www.figlet.org/under UNIX utilities.\n");
                return 1;
            case '?':
            default:
                print_usage(stderr);
                return 1;
        }
    }
    if (infocode >= 0) {
        switch (infocode) {
            case 0: print_version(); break;
            case 1: printf("20205\n"); break;
            case 2: printf("%s\n", fontdir); break;
            case 3: printf("%s\n", fontname); break;
            case 4: printf("%d\n", outputwidth); break;
            case 5: printf("flf2 tlf2\n"); break;
            default: break;
        }
        return 0;
    }
    for (size_t i = 0; i < ncontrols; i++) load_control_file(controls[i]);
    load_font();
    resolve_modes();
    if (optind < argc) {
        cmdline_mode = 1;
        cmd_argv = argv;
        cmd_argc = argc;
        cmd_index = optind;
        cmd_ptr = (const unsigned char *)argv[optind];
    } else {
        cmdline_mode = 0;
    }
    for (;;) {
        Item *items = NULL;
        size_t nitems = 0, items_cap = 0;
        int ended_newline = 0, hit_eof = 0;
        int saw_any_char = 0;
        for (;;) {
            CharResult r = next_translated();
            if (r.eof) { hit_eof = 1; break; }
            saw_any_char = 1;
            long c = r.code;
            if (c == 9) c = 32;
            if (is_newline_code(c)) { ended_newline = 1; break; }
            if (c >= 0 && ((c > 0 && c < 32) || c == 127)) continue;
            Glyph *g = lookup_glyph(c);
            if (!g) g = lookup_glyph(0);
            if (!g) continue;
            if (nitems == items_cap) {
                items_cap = items_cap ? items_cap * 2 : 64;
                items = xrealloc(items, items_cap * sizeof(*items));
            }
            items[nitems].g = g;
            items[nitems].is_space = (c == 32);
            nitems++;
        }
        if (hit_eof && nitems == 0 && !saw_any_char) {
            free(items);
            break;
        }
        render_logical_line(items, nitems, ended_newline);
        free(items);
        if (hit_eof) break;
    }
    return 0;
}
