    for (int i = 0; i < charheight; i++) {
        const wchar_t *lrow = resolved_direction ? g->rows[i] : out->rows[i];
        const wchar_t *rrow = resolved_direction ? out->rows[i] : g->rows[i];
        size_t llen = resolved_direction ? (size_t)g->width : (size_t)out->outlen;
        size_t rlen = resolved_direction ? (size_t)out->outlen : (size_t)g->width;
        size_t lact = wcslen(lrow), ract = wcslen(rrow);
        size_t trail = 0;
        while (trail < llen) {
            size_t idx = llen - 1 - trail;
            wchar_t c = (idx < lact) ? lrow[idx] : L'\\0';
            if (c == L' ' || c == L'\\0') trail++;
            else break;
        }
        size_t lead = 0;
        while (lead < rlen) {
            wchar_t c = (lead < ract) ? rrow[lead] : L'\\0';
            if (c == L' ' || c == L'\\0') lead++;
            else break;
