typedef struct {
    OutputLine cur, snapshot;
    int snapshot_valid;
    Glyph **curword;
    size_t curword_n, curword_cap;
    int in_space_run;
    int discard_spaces;
    int segments;
    int limit;
} RenderState;
static void render_init(RenderState *st) {
    out_init(&st->cur);
    out_init(&st->snapshot);
    st->snapshot_valid = 0;
    st->curword = NULL; st->curword_n = 0; st->curword_cap = 0;
    st->in_space_run = 0; st->discard_spaces = 0; st->segments = 0;
    st->limit = (outputwidth == 1) ? 0 : outputwidth - 1;
}
static void render_free(RenderState *st) {
    free(st->curword);
    out_free(&st->cur);
    out_free(&st->snapshot);
}
static void render_push_curword(RenderState *st, Glyph *g) {
    if (st->curword_n == st->curword_cap) {
        st->curword_cap = st->curword_cap ? st->curword_cap * 2 : 16;
        st->curword = xrealloc(st->curword, st->curword_cap * sizeof(*st->curword));
    }
    st->curword[st->curword_n++] = g;
}
static void render_add_within_word(RenderState *st, Glyph *g) {
    int amt = compute_amount(&st->cur, g);
    if (st->cur.has_any && st->cur.outlen + g->width - amt > st->limit) {
        print_output_line(&st->cur);
        st->segments++;
        out_clear(&st->cur);
        st->curword_n = 0;
        st->snapshot_valid = 0;
        amt = compute_amount(&st->cur, g);
    }
    add_glyph(&st->cur, g, amt);
    render_push_curword(st, g);
}
static void render_item(RenderState *st, Glyph *g, int is_space) {
    if (is_space && st->discard_spaces) return;
    if (!is_space) st->discard_spaces = 0;
    if (is_space) {
        if (!st->in_space_run) {
            if (st->curword_n > 0) {
                out_clone(&st->snapshot, &st->cur);
                st->snapshot_valid = 1;
                st->curword_n = 0;
            }
            st->in_space_run = 1;
        }
        int amt = compute_amount(&st->cur, g);
        if (st->cur.has_any && st->cur.outlen + g->width - amt > st->limit) {
            if (st->snapshot_valid) print_output_line(&st->snapshot);
            else print_output_line(&st->cur);
            st->segments++;
            out_clear(&st->cur);
            st->snapshot_valid = 0;
            st->curword_n = 0;
            st->in_space_run = 0;
            st->discard_spaces = 1;
            return;
        }
        add_glyph(&st->cur, g, amt);
    } else {
        st->in_space_run = 0;
        int amt = compute_amount(&st->cur, g);
        if (st->cur.has_any && st->cur.outlen + g->width - amt > st->limit) {
            if (st->snapshot_valid) {
                size_t saved_n = st->curword_n;
                Glyph **saved = NULL;
                if (saved_n) {
                    saved = xmalloc(saved_n * sizeof(*saved));
                    memcpy(saved, st->curword, saved_n * sizeof(*saved));
                }
                print_output_line(&st->snapshot);
                st->segments++;
                out_clear(&st->cur);
                st->snapshot_valid = 0;
                st->curword_n = 0;
                for (size_t k = 0; k < saved_n; k++) render_add_within_word(st, saved[k]);
                free(saved);
                render_add_within_word(st, g);
            } else {
                print_output_line(&st->cur);
                st->segments++;
                out_clear(&st->cur);
                st->curword_n = 0;
                render_add_within_word(st, g);
            }
        } else {
            add_glyph(&st->cur, g, amt);
            render_push_curword(st, g);
        }
    }
}
static void render_finish_line(RenderState *st, int explicit_newline) {
    if (explicit_newline) {
        if (st->cur.has_any || st->segments == 0) print_output_line(&st->cur);
        out_clear(&st->cur);
        st->snapshot_valid = 0;
        st->curword_n = 0;
        st->in_space_run = 0;
        st->discard_spaces = 0;
        st->segments = 0;
    } else if (st->cur.outlen > 0) {
        print_output_line(&st->cur);
    }
}

